namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(new[]
        {
            CreateNotification("Welcome to the notification center!"),
            CreateNotification("Your profile was updated successfully."),
            CreateNotification("New comment on your post."),
        });
    }

    /// <summary>Returns all notifications available at this moment.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return _notifications.ToList();
        }
    }

    /// <summary>Returns only notifications with an Id greater than <paramref name="sinceId"/>.</summary>
    public List<Notification> GetSince(int sinceId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > sinceId).ToList();
        }
    }

    /// <summary>Simulates new notifications arriving over time.</summary>
    public void SimulateIncoming()
    {
        string[] templates =
        [
            "You have a new follower.",
            "Someone liked your post.",
            "Server deployment completed.",
            "Reminder: meeting in 15 minutes.",
            "Your export is ready to download.",
            "Password changed successfully.",
        ];

        lock (_lock)
        {
            var message = templates[Random.Shared.Next(templates.Length)];
            _notifications.Add(CreateNotification(message));
        }
    }

    private Notification CreateNotification(string message)
    {
        return new Notification(_nextId++, message, DateTime.UtcNow);
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService Svc
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill">@notifications.Count</span>
</h1>

@if (notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>@n.Message</div>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> notifications = new();
    private CancellationTokenSource? cts;

    // Runs during SSR *and* on interactive re-render.
    // On SSR it populates the list for fast HTML.
    // On interactive re-render we skip re-fetching because
    // PersistentComponentState supplies the data.
    [Inject] private PersistentComponentState PersistentState { get; set; } = default!;
    private PersistingComponentStateSubscription? persistSub;

    protected override void OnInitialized()
    {
        // During SSR, register a callback that will serialize the data
        // into the rendered HTML so the interactive runtime can pick it up.
        persistSub = PersistentState.RegisterOnPersisting(() =>
        {
            PersistentState.PersistAsJson(nameof(notifications), notifications);
            return Task.CompletedTask;
        });

        // Try to restore persisted state (interactive render).
        if (PersistentState.TryTakeFromJson<List<Notification>>(
                nameof(notifications), out var restored))
        {
            notifications = restored!;
        }
        else
        {
            // First render (SSR) — load from service.
            notifications = Svc.GetAll();
        }
    }

    // Called only on the interactive render — never during SSR.
    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (!firstRender) return;

        cts = new CancellationTokenSource();
        _ = PollForNotificationsAsync(cts.Token);
        await Task.CompletedTask;
    }

    private async Task PollForNotificationsAsync(CancellationToken token)
    {
        // Determine the high-water mark from existing notifications.
        var lastId = notifications.Count > 0
            ? notifications.Max(n => n.Id)
            : 0;

        while (!token.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), token);

                // Simulate a new notification arriving roughly half the time.
                if (Random.Shared.Next(2) == 0)
                    Svc.SimulateIncoming();

                var newer = Svc.GetSince(lastId);
                if (newer.Count > 0)
                {
                    notifications.AddRange(newer);
                    lastId = newer.Max(n => n.Id);

                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (TaskCanceledException)
            {
                break;
            }
        }
    }

    public void Dispose()
    {
        persistSub?.Dispose();
        cts?.Cancel();
        cts?.Dispose();
    }
}

